import { Box, Container, Stack, Typography } from "@mui/material";
import masterData from "../../data/masterData.json";
import { getIcon } from "../../utils/iconMap";
import LeadFormCard from "./LeadFormCard";

export default function HeroSection() {
  const { brand, hero } = masterData;

  return (
    <Box
      sx={{
        position: "relative",
        overflow: "hidden",
        background:
          "radial-gradient(ellipse 80% 60% at 70% 40%, #D6E8FF 0%, transparent 55%), linear-gradient(180deg, #F4F8FF 0%, #EEF4FC 45%, #FFFFFF 100%)",
        pt: { xs: 2, md: 2.5 },
        pb: { xs: 3, md: 0 },
        minHeight: { md: 640 },
      }}
    >
      {/* Soft network dots pattern */}
      <Box
        sx={{
          position: "absolute",
          inset: 0,
          opacity: 0.35,
          backgroundImage:
            "radial-gradient(circle, rgba(0,86,210,0.18) 1px, transparent 1px)",
          backgroundSize: "28px 28px",
          pointerEvents: "none",
        }}
      />

      <Container maxWidth="lg" sx={{ position: "relative", zIndex: 2 }}>
        {/* Logo */}
        <Stack direction="row" alignItems="center" spacing={1.1} sx={{ mb: { xs: 2.5, md: 3.5 } }}>
          <Box component="img" src={brand.logo} alt={brand.name} sx={{ width: 34, height: 34 }} />
          <Typography
            sx={{
              fontWeight: 800,
              fontSize: 14,
              letterSpacing: "0.08em",
              color: "#0B1F3A",
            }}
          >
            {brand.name}
          </Typography>
        </Stack>

        <Box
          sx={{
            display: "grid",
            gridTemplateColumns: {
              xs: "1fr",
              md: "minmax(0, 1.05fr) minmax(0, 0.85fr) minmax(320px, 0.95fr)",
            },
            gap: { xs: 3, md: 2 },
            alignItems: "start",
          }}
        >
          {/* Left copy */}
          <Box sx={{ pt: { md: 1 }, position: "relative", zIndex: 3 }}>
            <Typography
              sx={{
                color: "#0056D2",
                fontWeight: 700,
                fontSize: 11,
                letterSpacing: "0.14em",
                mb: 1.5,
              }}
            >
              {brand.eyebrow}
            </Typography>

            <Typography
              component="h1"
              sx={{
                fontWeight: 800,
                color: "#0B1F3A",
                fontSize: { xs: "1.7rem", sm: "2.1rem", md: "2.45rem" },
                lineHeight: 1.18,
                mb: 1.75,
                letterSpacing: "-0.02em",
              }}
            >
              {hero.headlineBefore}
              <Box component="span" sx={{ color: "#0056D2" }}>
                {hero.headlineHighlight}
              </Box>
            </Typography>

            <Typography
              sx={{
                fontWeight: 700,
                color: "#0B1F3A",
                fontSize: { xs: 15, md: 17 },
                mb: 1.25,
              }}
            >
              {hero.subheadline}
            </Typography>

            <Box sx={{ position: "relative", mb: 2.5, maxWidth: 420 }}>
              <Typography
                sx={{
                  color: "#5A6B80",
                  fontSize: { xs: 13.5, md: 14.5 },
                  lineHeight: 1.7,
                  pr: { md: 6 },
                }}
              >
                {hero.description}
              </Typography>
              <Typography
                sx={{
                  display: { xs: "none", md: "block" },
                  position: "absolute",
                  right: -8,
                  top: 8,
                  width: 110,
                  fontFamily: "'Segoe Script', 'Brush Script MT', cursive",
                  fontSize: 13,
                  lineHeight: 1.25,
                  color: "#0056D2",
                  fontWeight: 600,
                  textAlign: "right",
                  transform: "rotate(-6deg)",
                  whiteSpace: "pre-line",
                }}
              >
                {hero.scriptText}
              </Typography>
            </Box>

            {/* Stats */}
            <Stack
              direction="row"
              flexWrap="wrap"
              useFlexGap
              spacing={{ xs: 2, md: 2.5 }}
              alignItems="center"
              sx={{ mb: 2 }}
            >
              {hero.stats.map((stat) => {
                const Icon = getIcon(stat.icon);
                return (
                  <Stack key={stat.id} direction="row" spacing={1} alignItems="center">
                    <Box
                      sx={{
                        width: 34,
                        height: 34,
                        borderRadius: "50%",
                        bgcolor: "#E5F0FF",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        flexShrink: 0,
                      }}
                    >
                      <Icon sx={{ color: "#0056D2", fontSize: 18 }} />
                    </Box>
                    <Typography sx={{ fontSize: 12.5, fontWeight: 700, color: "#0B1F3A", lineHeight: 1.25 }}>
                      {stat.value ? (
                        <>
                          <Box component="span" sx={{ color: "#0056D2" }}>
                            {stat.value}
                          </Box>{" "}
                          {stat.label}
                        </>
                      ) : (
                        stat.label
                      )}
                    </Typography>
                  </Stack>
                );
              })}
            </Stack>

            {/* CPD badge */}
            <Stack
              direction="row"
              alignItems="center"
              spacing={1.25}
              sx={{
                display: "inline-flex",
                bgcolor: "#fff",
                border: "1px solid #E0EAF6",
                borderRadius: "999px",
                px: 1.5,
                py: 0.75,
                boxShadow: "0 4px 14px rgba(0,86,210,0.08)",
              }}
            >
              <Box
                component="img"
                src={hero.cpdBadge}
                alt="CPD"
                sx={{ width: 36, height: 36 }}
              />
              <Typography sx={{ fontSize: 12, fontWeight: 600, color: "#0B1F3A" }}>
                {hero.cpdLabel}
              </Typography>
            </Stack>
          </Box>

          {/* Center doctor */}
          <Box
            sx={{
              display: { xs: "none", md: "flex" },
              justifyContent: "center",
              alignItems: "flex-end",
              position: "relative",
              height: "100%",
              minHeight: 520,
              zIndex: 1,
            }}
          >
            <Box
              sx={{
                position: "absolute",
                bottom: 0,
                width: 280,
                height: 280,
                borderRadius: "50%",
                background: "radial-gradient(circle, #B7D4FF 0%, transparent 70%)",
                filter: "blur(8px)",
                zIndex: 0,
              }}
            />
            <Box
              component="img"
              src={hero.image}
              alt="Doctor"
              sx={{
                position: "relative",
                zIndex: 1,
                width: "100%",
                maxWidth: 360,
                height: 540,
                objectFit: "cover",
                objectPosition: "top center",
                maskImage: "linear-gradient(to bottom, #000 78%, transparent 100%)",
                WebkitMaskImage: "linear-gradient(to bottom, #000 78%, transparent 100%)",
              }}
            />
          </Box>

          {/* Right form */}
          <Box
            sx={{
              display: "flex",
              justifyContent: { xs: "stretch", md: "flex-end" },
              pt: { md: 0.5 },
              pb: { md: 4 },
              position: "relative",
              zIndex: 4,
            }}
          >
            <LeadFormCard />
          </Box>
        </Box>

        {/* Mobile doctor */}
        <Box
          sx={{
            display: { xs: "flex", md: "none" },
            justifyContent: "center",
            mt: 2,
          }}
        >
          <Box
            component="img"
            src={hero.image}
            alt="Doctor"
            sx={{
              width: "70%",
              maxWidth: 280,
              height: 320,
              objectFit: "cover",
              objectPosition: "top",
              borderRadius: 2,
            }}
          />
        </Box>
      </Container>
    </Box>
  );
}
